  line-height: 40px;
  background: transparent;
  border-radius: 100%;
  right: 0;
  top: 0;
}
.rs-features .feature-wrap .icon-part .circle-anim:after {
  position: absolute;
  content: '';
  right: -13px;
  top: -6px;
  width: 100%;
  height: 100%;
  border: 1px dashed #010d14;
  border-radius: 100%;
  z-index: 0;
  transition: all 0.4s ease-in-out 0s;
  animation: spine 10s linear infinite;
  -webkit-animation: spine 10s linear infinite;
}
.rs-features .feature-wrap .icon-part .circle-anim:before {
  position: absolute;
  content: '';
  right: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background: #d6fbff;
  border-radius: 100%;
  z-index: 1;
  transition: all 0.4s ease-in-out 0s;
}
