-----------------------------------------------*/
.rs-addon-number--s .services-wrap{
	position: relative;
	padding: 30px 30px 30px 58px;
	background-color: #FFFFFF;
	border: 0.5px solid #eaeaea;
}
.rs-addon-number--s .services-wrap .number-box span{
	z-index: 2;
	position: relative;
}
.rs-addon-number--s .services-wrap .number-box span:after{
	background: #ee5c03;
	content: "";
	position: absolute;
	z-index: -1;
	left: 50%;
	top: 50%;
	visibility: hidden;
	opacity: 0;
	transform: translateX(-50%) translateY(-50%);
	display: block;
	width: 85px;
	height: 85px;
	border-radius: 50%;
	-webkit-animation: pulse-border 1500ms ease-out infinite;
	animation: pulse-border 1500ms ease-out infinite;
}
.rs-addon-number--s .services-wrap:hover .number-box span::after {
    visibility: visible;
    opacity: 1;
}
.rs-addon-number--s .services-wrap .number-box span:before{
	content: "";
	position: absolute;
	z-index: -1;
	left: 50%;
	top: 50%;
	transform: translateX(-50%) translateY(-50%);
	display: block;
	width: 85px;
	height: 85px;
	border-radius: 50%;
	transition: all 200ms;
	visibility: hidden;
	opacity: 0;
}
.rs-addon-number--s .services-wrap .number-box{
